package br.com.codice.aventureiro;
import android.app.*;import android.content.pm.*;import android.webkit.WebView;import android.os.*;import java.io.*;import java.net.*;import java.security.*;import java.security.cert.*;import java.util.*;import java.util.zip.*;import org.json.*;
/** Signed, complete asset snapshots. Never loads remotely hosted HTML into the bridge. */
final class Update595 {
 final Activity activity; final WebView web; final File root; final Set<String> allowed; volatile boolean busy; static final int BASE=213; static final long LIMIT=80L*1024*1024;
 Update595(Activity a,WebView w,Set<String> paths){activity=a;web=w;allowed=paths;root=new File(a.getFilesDir(),"codex-updates595");root.mkdirs();}
 android.content.SharedPreferences prefs(){return activity.getSharedPreferences("codex-updates595",0);}
 int current(){return prefs().getInt("current",BASE);}
 File active(String path){int v=current();if(v<=BASE)return null;File f=new File(new File(root,"v"+v),path.substring(1));return f.isFile()?f:null;}
 void message(String s){activity.runOnUiThread(()->new AlertDialog.Builder(activity).setTitle("Codex — Software Update").setMessage(s).setPositiveButton("OK",null).show());}
 void check(boolean manual){if(busy)return;if(!UpdateConfig595.MANIFEST.startsWith("https://")){if(manual)message("Update server is not configured.");return;}busy=true;new Thread(()->{try{byte[] bytes=download(UpdateConfig595.MANIFEST,65536);JSONObject envelope=new JSONObject(new String(bytes,"UTF-8"));byte[] payload=android.util.Base64.decode(envelope.getString("payload"),android.util.Base64.DEFAULT),sig=android.util.Base64.decode(envelope.getString("signature"),android.util.Base64.DEFAULT);verify(payload,sig);JSONObject m=new JSONObject(new String(payload,"UTF-8"));int code=m.getInt("code");if(code<=current()||code< prefs().getInt("highest",BASE)){if(manual)message("No newer update available.");busy=false;return;}if(m.getInt("minNativeCode")>BASE)throw new IOException("A new APK is required.");String url=m.getString("url"),hash=m.getString("sha256");if(!url.startsWith("https://")||!hash.matches("[0-9a-f]{64}"))throw new IOException("Invalid signed manifest");activity.runOnUiThread(()->new AlertDialog.Builder(activity).setTitle("Codex "+m.optString("version")).setMessage(m.optString("notes","Update available")+"\n\nYour local character sheets will be kept.").setPositiveButton("Download & apply",(d,n)->install(code,url,hash)).setNegativeButton("Later",(d,n)->busy=false).setOnCancelListener(d->busy=false).show());}catch(Exception e){busy=false;if(manual)message("Could not check updates: "+e.getMessage());}}).start();}
 void verify(byte[] payload,byte[] sig)throws Exception{PackageInfo info=activity.getPackageManager().getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNATURES);if(info.signatures==null||info.signatures.length!=1)throw new SecurityException("Signing identity unavailable");java.security.cert.Certificate cert=CertificateFactory.getInstance("X.509").generateCertificate(new ByteArrayInputStream(info.signatures[0].toByteArray()));java.security.Signature verifier=java.security.Signature.getInstance("SHA256withRSA");verifier.initVerify(cert.getPublicKey());verifier.update(payload);if(!verifier.verify(sig))throw new SecurityException("Invalid update signature");}
 static byte[] download(String address,long limit)throws Exception{URL url=new URL(address);for(int redirects=0;redirects<6;redirects++){if(!"https".equals(url.getProtocol()))throw new IOException("HTTPS required");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(30000);try{int status=c.getResponseCode();if(status>=300&&status<400){url=new URL(url,c.getHeaderField("Location"));continue;}if(status!=200)throw new IOException("HTTP "+status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>limit)throw new IOException("Download too large");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}throw new IOException("Too many redirects");}
 static String hex(byte[] a){StringBuilder s=new StringBuilder();for(byte b:a)s.append(String.format(Locale.US,"%02x",b&255));return s.toString();}
 static void remove(File f){if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File child:children)remove(child);}f.delete();}
 void install(int code,String url,String hash){ProgressDialog progress=new ProgressDialog(activity);progress.setMessage("Downloading and verifying update…");progress.setCancelable(false);progress.show();new Thread(()->{File stage=new File(root,"staging");try{byte[] zip=download(url,LIMIT);if(!hex(MessageDigest.getInstance("SHA-256").digest(zip)).equals(hash))throw new SecurityException("Checksum mismatch");remove(stage);if(!stage.mkdir())throw new IOException("Cannot create staging directory");Set<String> seen=new HashSet<>();long total=0;try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(zip))){ZipEntry e;byte[] b=new byte[32768];while((e=in.getNextEntry())!=null){String path="/"+e.getName();if(e.isDirectory()||!allowed.contains(path)||!seen.add(path))throw new SecurityException("Unexpected update file");try(FileOutputStream out=new FileOutputStream(new File(stage,e.getName()))){int n;while((n=in.read(b))!=-1){total+=n;if(total>LIMIT)throw new IOException("Expanded package too large");out.write(b,0,n);}out.getFD().sync();}}}if(!seen.equals(allowed))throw new SecurityException("Incomplete update package");File dest=new File(root,"v"+code);remove(dest);if(!stage.renameTo(dest))throw new IOException("Could not activate update");int prev=current();if(!prefs().edit().putInt("previous",prev).putInt("current",code).putInt("highest",code).commit())throw new IOException("Could not save version");activity.runOnUiThread(()->{progress.dismiss();busy=false;web.evaluateJavascript("typeof save==='function'&&save()",ignored->{web.clearCache(true);web.reload();});});}catch(Exception e){remove(stage);activity.runOnUiThread(()->progress.dismiss());busy=false;message("Update failed: "+e.getMessage());}}).start();}
 void rollback(){if(busy)return;int prev=prefs().getInt("previous",BASE);if(current()==prev||prev>BASE&&!new File(root,"v"+prev).isDirectory()){message("No previous update available.");return;}new AlertDialog.Builder(activity).setTitle("Restore previous version?").setMessage("Character data will not be deleted. Export a backup first if possible.").setNegativeButton("Cancel",null).setPositiveButton("Restore",(d,n)->{int old=current();if(prefs().edit().putInt("current",prev).putInt("previous",old).commit()){web.evaluateJavascript("typeof save==='function'&&save()",ignored->{web.clearCache(true);web.reload();});}}).show();}
}
